"use server";

import { prisma } from "src/generated"; // Senin output klasörün burasıydı
import { revalidatePath } from "next/cache";
import { TaskStatus } from "@/src/generated"; // Prisma'dan gelen Enum

// Yeni Görev Ekleme
export async function createScrumTask(title: string, status: TaskStatus, userId: string) {
  await prisma.task.create({
    data: {
      title,
      status,
      userId,
    },
  });
  revalidatePath("/scrumboard");
}

// Durum Güncelleme (Sürükle-Bırak)
export async function updateTaskStatus(taskId: string, newStatus: TaskStatus) {
  await prisma.task.update({
    where: { id: taskId },
    data: { status: newStatus },
  });
  revalidatePath("/scrumboard");
}

// Silme
export async function deleteScrumTask(taskId: string) {
  await prisma.task.delete({
    where: { id: taskId },
  });
  revalidatePath("/scrumboard");
}